  "generation.sampler.title": "Сэмплер",
  "generation.sampler.label": "Сэмплер",
  "generation.sampler.label_tip": "Алгоритм, который постепенно удаляет шум из изображения. Разные сэмплеры дают разные результаты — 'euler' быстрый и надёжный, варианты 'dpmpp' дают более высокое качество, 'ancestral' добавляют случайность для разнообразия.",
  "generation.sampler.scheduler": "Планировщик",
  "generation.sampler.scheduler_tip": "Управляет распределением шума между шагами. 'normal' — стандартный, 'karras' концентрирует работу с деталями в начале для более чётких результатов, 'sgm_uniform' равномерно распределяет шаги.",
  "generation.sampler.scheduler_flux2_note": "Flux2 использует фиксированный внутренний планировщик",
  "generation.sampler.steps": "Шаги",
  "generation.sampler.steps_tip": "Количество итераций удаления шума. Больше шагов = более тонкие детали, но медленнее. 20-30 — хороший баланс для большинства сэмплеров.",
  "generation.sampler.cfg": "CFG",
  "generation.sampler.cfg_tip": "Classifier-Free Guidance — насколько точно ИИ следует вашему промпту. Выше = более буквальное следование, но может выглядеть искусственно. Ниже = более креативно, но может игнорировать части промпта.",
  "generation.sampler.seed": "Сид",
  "generation.sampler.seed_tip": "Число, определяющее 'случайность' вашего изображения. Тот же сид + те же настройки = то же изображение. Используйте 'Случайный' для разнообразия или задайте конкретный сид для воспроизведения результата.",
  "generation.sampler.seed_random": "Случ.",
  "generation.sampler.random_display": "Случайный",
  "generation.sampler.seed_use_last": "Последний",
  "generation.sampler.seed_use_last_tip": "Использовать сид последней генерации",
  "generation.sampler.batch": "Пакет",
  "generation.sampler.batch_tip": "Сколько изображений генерировать за раз. Большие значения используют больше VRAM, но позволяют быстро сравнить результаты.",
  "generation.sampler.denoise": "Шумоподавление",
  "generation.sampler.denoise_tip": "Насколько сильно ИИ перерисовывает входное изображение. Низкие значения (0.2-0.4) сохраняют оригинал, высокие (0.5-0.8) добавляют больше деталей, но меняют больше.",
  "generation.sampler.bit_depth": "Битность",
  "generation.sampler.bit_depth_tip": "8-бит — стандарт. 16-бит сохраняет больше точности из float32-вывода модели — полезно для последующей обработки в Photoshop/GIMP.",
  "generation.sampler.bit_8": "8-бит",
