  "generation.sampler.bit_16_webp_disabled": "Вывод WebP всегда 8-битный: у WebP без потерь нет 16-битного режима. Выберите PNG или JXL для 16-битного вывода.",
  "generation.sampler.metadata": "Метаданные",
