  "generation.model.checkpoint": "Чекпоинт",
  "generation.model.checkpoint_tip": "ИИ-модель, генерирующая ваши изображения. Разные чекпоинты обучены на разных стилях — аниме, фотореализм, иллюстрация и т.д.",
