  "generation.model.clip_model": "Модель CLIP",
  "generation.model.vae_tip": "Вариационный автоэнкодер — конвертирует между пиксельными изображениями и латентным пространством, в котором работает ИИ. 'Автоматически' использует встроенный в чекпоинт, что обычно лучше всего.",
  "generation.model.lora_tip": "Low-Rank Adaptations — небольшие дополнительные модели, которые модифицируют стиль чекпоинта или обучают его новым концепциям (персонажи, стили, объекты) без замены всей модели.",
  "generation.model.lora_strength_model_tip": "Насколько сильно этот LoRA влияет на модель генерации изображений. Более высокие значения = более сильный эффект, но слишком высокие могут исказить изображение.",
  "generation.model.lora_strength_clip_tip": "Насколько сильно этот LoRA влияет на понимание текста. Контролирует, как сильно LoRA изменяет то, что ИИ 'видит' в вашем промпте.",
