  "generation.model.text_encoder": "Текстовый энкодер",
  "generation.model.text_encoder_tip": "Текстовый энкодер для раздельных моделей. Показывает файлы из папок text_encoders/ и clip/.",
  "generation.model.text_encoder_none": "Не выбрано",
  "generation.model.krea2_encoder_warning": "Krea 2 требует текстовый энкодер Qwen3-VL-4B (например, qwen3vl_4b_fp8_scaled.safetensors). Другие энкодеры завершатся ошибкой размера conditioning. Выберите его выше или выберите модель заново для автоматической загрузки.",
  "generation.model.wrong_kind.model_is_text_encoder": "{file} — это текстовый энкодер, а не модель. Сам по себе он не генерирует изображения. Выберите его в поле «Текстовый энкодер», а здесь выберите чекпоинт или диффузионную модель.",
  "generation.model.wrong_kind.model_is_vae": "{file} — это VAE, а не модель. Сам по себе он не генерирует изображения. Выберите его в поле VAE, а здесь выберите чекпоинт или диффузионную модель.",
  "generation.model.wrong_kind.vae_is_text_encoder": "{file} — это текстовый энкодер, а не VAE. Выберите его в поле «Текстовый энкодер», а здесь выберите VAE (или «Автоматически»).",
  "generation.model.wrong_kind.vae_is_model": "{file} — это модель, а не VAE. Выберите её как модель, а здесь выберите VAE (или «Автоматически»).",
  "generation.model.wrong_kind.clip_is_vae": "{file} — это VAE, а не текстовый энкодер. Выберите его в поле VAE, а здесь выберите текстовый энкодер.",
  "generation.model.wrong_kind.clip_is_model": "{file} — это модель, а не текстовый энкодер. Выберите её как модель, а здесь выберите текстовый энкодер.",
  "generation.model.krea2_uncensored_title": "Режим без цензуры",
  "generation.model.krea2_uncensored_tip": "Krea 2 читает промпты через Qwen3-VL-4B, чат-модель, обученную отказывать в некоторых запросах, а её слои TextFusion научились ослаблять такие понятия, поэтому они могут ослабляться или пропадать на изображении (не только NSFW). Режим без цензуры использует abliterated-копию (Heretic) того же энкодера и добавляет LoRA снижения отказов TextFusion от Capitan01R с силой 1.0. LoRA применяется автоматически только к генерациям Krea 2 и не отображается в вашем списке LoRA. Она не может добавить понятия, которым модель изображений не обучалась.",
