  "generation.video.megapixels": "Бюджет пикселей",
  "generation.video.megapixels_tip": "Всего пикселей на кадр. Ширина и высота выводятся отсюда и из соотношения сторон, округляясь до кратных 32. Большой бюджет требует намного больше видеопамяти.",
  "generation.video.resolution": "Разрешение вывода: {width} x {height}",
