  "generation.video.vram_warning_tight": "Приблизительная оценка VRAM без выгрузки на CPU: {required} ГБ, близко к оценке доступного объёма {usable} ГБ на вашей видеокарте с {detected} ГБ. Реальное использование зависит от пользовательских моделей и настроек памяти.",
  "generation.video.vram_nvfp4_emulated": "Модель NVFP4 здесь занимает дополнительную память: ускорение FP4 требует видеокарты Blackwell (серия RTX 50), поэтому веса расширяются во время работы.",
  "generation.video.vram_suggest": "Использовать {megapixels} МП",
