  "generation.video.stack_requires_blackwell": "Для NVFP4 нужна карта Blackwell (серия RTX 50). На более старых картах используется значительно более медленный путь.",
  "generation.video.h3_guide.title": "Формат промпта H3",
  "generation.video.h3_guide.intro": "H3 обучали на промптах, разбитых на именованные разделы, а не на свободном тексте. Пишите разделы по порядку, разделяя их пустой строкой.",
  "generation.video.h3_guide.applies": "Текущие настройки: {task}, {frames} кадров при {fps} fps ({seconds} с).",
  "generation.video.h3_guide.instruction_line": "Строка инструкции",
  "generation.video.h3_guide.section_instruction": "Идет первой, за ней одна пустая строка. Она сообщает H3, на какой момент видео приходится каждое референсное изображение.",
  "generation.video.h3_guide.section_integrated": "Все видео, план за планом. Начните с [Shot 1], сразу после него укажите визуальный стиль, затем по порядку опишите действие, движения камеры и реплики. Каждый следующий план начинается с отметки времени.",
  "generation.video.h3_guide.section_subjects": "По одной записи на каждый помеченный вход: <Subject 1>, <Picture 1>, <Video 1>, <Audio 1>. Опишите, что это, а не что оно должно делать.",
  "generation.video.h3_guide.section_summary": "Один абзац, начинающийся с типа задачи в квадратных скобках: keyframe completion, reference generation, video editing, video continuation, audio reuse или audio reference. Несколько типов соединяются знаком плюс.",
  "generation.video.h3_guide.section_retention": "По строке на метку с указанием, насколько точно ей следовать. Для изображения: fully_preserved, partially_preserved, attribute_transfer или weak_reference; для звука: fully_copy, partially_copy, reference или weak_reference.",
  "generation.video.h3_guide.section_detailed": "Описание план за планом. Здесь визуальный стиль указывается до [Shot 1], а кадры привязываются оборотами вроде the shot begins from <Picture 1>. Ориентир: от 350 до 500 слов.",
  "generation.video.h3_guide.section_soundscape": "От одного до четырех предложений об окружающих, физических и невербальных человеческих звуках. Без реплик, пения и музыки. Для тишины напишите N/A.",
  "generation.video.h3_guide.section_music": "От одного до трех предложений о музыке: инструменты, темп, ритм и динамика. Описывайте исполнение, а не настроение. Если музыки нет, напишите N/A.",
  "generation.video.h3_guide.rules_title": "Самые важные правила",
  "generation.video.h3_guide.rule_shots": "У первого плана отметки времени нет. Все следующие начинаются с нее, по возрастанию.",
  "generation.video.h3_guide.rule_style": "Склейка стирает стиль, заданный в Shot 1. Повторяйте его в начале каждого следующего кадра и указывайте референс, с которого кадр начинается, если он есть.",
  "generation.video.h3_guide.rule_camera": "У каждого движения камеры должны быть тип, амплитуда и скорость.",
  "generation.video.h3_guide.rule_dialogue": "Говорящий указывается вне тега, внутри остаются только язык и сами слова.",
  "generation.video.h3_guide.rule_text": "Текст, видимый на экране, берется в двойные кавычки, переносится дословно и не переводится.",
  "generation.video.h3_guide.tab_structure": "Структура",
