  "generation.inpaint.differential_tip": "Рекомендуется для моделей типа v-pred / Anima при инпейнтинге, если вы не используете сэмплер CFG++. Помогает сохранить исходную структуру при редактировании замаскированных областей.",
  "generation.inpaint.area_tip": "Всё изображение: обрабатывается весь кадр, меняется только область маски. Только маска: вырезает область маски, семплирует в разрешении бокса через Crop & Stitch и бесшовно вшивает обратно без изменения остального кадра.",
