  "generation.sampler.output_format_tip": "PNG — стандартный формат с широкой поддержкой. JPEG XL (JXL) сжимает без потерь, примерно на 40% компактнее PNG и встраивает метаданные в SwarmUI-совместимый блок XMP. WebP сжимает без потерь (VP8L), поддерживается везде, всегда 8-битный и хранит метаданные в блоке EXIF. Изображения галереи декодируются по требованию для отображения.",
