  "generation.sampler.flux_guidance_tip": "Шкала дистиллированного гайданса для Flux Dev / Flux 2 Klein. Заменяет CFG (который эти модели игнорируют). Оптимальный диапазон: 2.5–4. Выше = более строгое следование промпту, но менее естественное изображение.",
